using namespace std;

int main() {
    int n, x;
    cin >> n >> x;
    vector<int> a(n);
    for (int &v : a) cin >> v;
    // TODO: tìm chỉ số đầu tiên của x

    return 0;
}

problem.solution:
#include <iostream>
#include <vector>
using namespace std;
int main() {
    int n, x; cin >> n >> x;
    vector<int> a(n); for (int &v : a) cin >> v;
    int l = 0, r = n - 1, ans = -1;
    while (l <= r) {
        int mid = l + (r - l) / 2;
        if (a[mid] >= x) {
            if (a[mid] == x) ans = mid;
            r = mid - 1;
        } else l = mid + 1;
    }
    cout << ans << '\n';
}

problem.starter:
#include <iostream>
#include <string>
#include <stack>
using namespace std;

int main() {
    string s;
    cin >> s;
    // TODO: kiểm tra thứ tự đóng/mở ngoặc

    return 0;
}

problem.solution:
#include <iostream>
#include <string>
#include <stack>
using namespace std;
int main() {
    string s; cin >> s;
    stack<char> st;
    for (char c : s) {
        if (c == '(') st.push(c);
        else {
            if (st.empty()) { cout << "NO\n"; return 0; }
            st.pop();
        }
    }
    cout << (st.empty() ? "YES\n" : "NO\n");
}
